<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:white;padding:16px 5vw;font-weight:900}main{max-width:1200px;margin:auto;padding:28px}.hero{display:flex;justify-content:space-between;gap:20px;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.hero p{color:#536771;font-size:18px}.panel{background:white;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.field{display:flex;flex-direction:column;gap:8px}.field.full{grid-column:1/-1}textarea,input{font:inherit;border:2px solid #dbe5e8;border-radius:12px;padding:12px}textarea{min-height:120px}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:8px 8px 0 0}.secondary{background:white}.race{background:#10283d;color:#d8f4f4;border-radius:14px;padding:12px}.lane{display:flex;gap:15px;align-items:center;border-bottom:1px dashed #6fc9d2;padding:10px}.lane span:first-child{width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.qr{display:flex;gap:18px;align-items:center;flex-wrap:wrap}.notice{background:#fff2bd;padding:12px;border-radius:10px;font-size:14px}.muted{color:#637780;font-size:14px}.results li{padding:8px;border-bottom:1px solid #ddd}@media(max-width:760px){.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.hero{display:block}main{padding:20px}.lane span:first-child{width:90px}}</style></head><body><header>PATO NA PISTA 🦆</header><main id="app"><div class="hero"><div><small>CORRIDA COM QR CODE</small><h1>Quem cruza a linha primeiro?</h1><p>Crie uma sala, compartilhe o QR code e receba os nomes em tempo real.</p></div><div style="font-size:90px">🦆</div></div><section class="panel" v-if="!race"><h2>Começar uma corrida</h2><p class="muted">O organizador cria a sala e exibe o QR code na tela.</p><button @click="createRace">Criar sala</button></section><template v-else><section class="panel"><div class="grid"><div class="field full"><label>Participantes (um por linha)</label><textarea v-model="textNames" @change="importNames"></textarea></div><div><strong>{{ race.names.length }} participantes</strong><p class="muted">Sala: {{ race.code }}</p><button @click="startRace">Começar corrida</button><button class="secondary" @click="exportCsv">Exportar CSV</button></div><div class="qr"><div id="qrcode"></div><div class="notice">Escaneie para entrar<br><strong>{{ joinUrl }}</strong></div></div></div></section><section class="panel"><h2>Corrida</h2><div class="race"><div class="lane" v-for="(name,i) in race.names"><span>{{ name }}</span><span>🦆</span><span>#{{ i+1 }}</span></div></div><div v-if="race.results" class="results"><h2>Resultado final</h2><ol><li v-for="r in race.results"><strong>{{ ['🥇','🥈','🥉'][r.position-1] || '🏁' }} {{ r.name }}</strong> — {{ r.position }}º lugar</li></ol></div></section></template></main><script>const {createApp}=Vue;createApp({data(){return{race:null,textNames:'',joinUrl:'',poll:null}},mounted(){const c=location.pathname.split('/').filter(Boolean).pop();if(c&&c!=='')this.load(c)},methods:{async createRace(){this.race=await(await fetch('/api/races',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content}})).json();this.setup()},async load(code){const r=await fetch('/api/races/'+code);if(r.ok){this.race=await r.json();this.setup()}},setup(){this.textNames=(this.race.names||[]).join('\n');this.joinUrl=location.origin+'/join/'+this.race.code;history.replaceState({},'', '/races/'+this.race.code);setTimeout(()=>new QRCode(document.getElementById('qrcode'),{text:this.joinUrl,width:150,height:150}),50);this.poll=setInterval(async()=>{this.race=await(await fetch('/api/races/'+this.race.code)).json();this.textNames=(this.race.names||[]).join('\n')},2500)},async importNames(){const names=this.textNames.split(/\n|,|;/).map(x=>x.trim()).filter(Boolean);this.race=await(await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({names})})).json()},async startRace(){this.race=await(await fetch('/api/races/'+this.race.code+'/start',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content}})).json()},exportCsv(){const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,nome,posicao%0A'+this.race.results.map(r=>r.name+','+r.position).join('%0A');a.download='resultado.csv';a.click()}}}).mount('#app')</script></body></html>
